let currentIndex=0;function renderCarousel(){const e=document.getElementById("carousel-track");e&&"undefined"!=typeof FEATURED_COINS_DATA&&(e.innerHTML=FEATURED_COINS_DATA.map((e,t)=>`\n        <div class="featured-card ${0===t?"active":""}" id="card-${t}">\n            <div class="featured-card-badge">🪙 ${e.metal} • ${e.period}</div>\n            <h2>${e.name}</h2>\n            <p class="featured-significance"><strong>Historical Significance:</strong> ${e.significance}</p>\n            <p class="featured-fact">💡 <strong>Interesting Fact:</strong> ${e.fact}</p>\n            <a href="${e.explorerUrl}" class="btn-explore">Explore ${e.name} →</a>\n        </div>\n    `).join(""))}function initCarouselControls(){const e=document.getElementById("btn-prev"),t=document.getElementById("btn-next");e&&t&&"undefined"!=typeof FEATURED_COINS_DATA&&(e.addEventListener("click",()=>{currentIndex=(currentIndex-1+FEATURED_COINS_DATA.length)%FEATURED_COINS_DATA.length,updateActiveCard()}),t.addEventListener("click",()=>{currentIndex=(currentIndex+1)%FEATURED_COINS_DATA.length,updateActiveCard()}),document.addEventListener("keydown",n=>{"ArrowLeft"===n.key&&e.click(),"ArrowRight"===n.key&&t.click()}))}function updateActiveCard(){document.querySelectorAll(".featured-card").forEach((e,t)=>{t===currentIndex?e.classList.add("active"):e.classList.remove("active")})}function initThemeToggle(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{const t=document.body.classList.toggle("light-theme");localStorage.setItem("theme",t?"light":"dark"),e.textContent=t?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderCarousel(),initCarouselControls(),initThemeToggle()});